//! — File-system experience archive.
//!
//! Bridges the experience entries generated by `harness_self_edit` with the
//! Researcher OS's `experience/` directory. Provides:
//!
//! 1. **ExperienceArchive**: Read/search/query over experience JSONL files.
//! 2. **Integration hooks**: Functions called from `researcher_loop` to
//!    record and surface experiences during the discover/step/daily cycle.
//! 3. **Rendering**: Convert experience entries into system-prompt blocks
//!    so the LLM can learn from past failures.
//!
//! ## Storage layout
//!
//! ```text
//! ~/.hermix/researcher/experience/
//!   ├── <timestamp>-<id>.jsonl   ← experience entries (append-only)
//!   └── index.json               ← optional metadata index
//! ```

use std::collections::HashMap;
use std::fs;
use std::io::{BufRead, BufReader};
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

use super::harness_self_edit::{
    ExperienceEntry, FailureKind,
};

// ---------------------------------------------------------------------------
// Experience index
// ---------------------------------------------------------------------------

/// Lightweight index entry for fast querying without loading full bodies.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ExperienceIndexEntry {
    /// Experience entry ID.
    pub id: String,
    /// Failure kind.
    pub failure_kind: FailureKind,
    /// Tools involved.
    pub tools: Vec<String>,
    /// Observation count.
    pub observation_count: u32,
    /// Unix timestamp of creation.
    pub created_at: u64,
    /// First 80 chars of `what_happened` for preview.
    pub preview: String,
}

// ---------------------------------------------------------------------------
// Experience archive
// ---------------------------------------------------------------------------

/// Read-only archive over the experience directory. Provides search,
/// retrieval, and rendering of past experiences.
#[derive(Debug)]
pub struct ExperienceArchive {
    /// Root directory containing experience JSONL files.
    root: PathBuf,
}

impl ExperienceArchive {
    /// Open the archive at the given root directory.
    /// Creates the directory if it doesn't exist.
    pub fn open(root: impl Into<PathBuf>) -> std::io::Result<Self> {
        let root = root.into();
        fs::create_dir_all(&root)?;
        Ok(Self { root })
    }

    /// Return the root path.
    pub fn root(&self) -> &Path {
        &self.root
    }

    /// Load all experience entries from all JSONL files.
    pub fn load_all(&self) -> std::io::Result<Vec<ExperienceEntry>> {
        let mut entries = Vec::new();
        if !self.root.exists() {
            return Ok(entries);
        }

        for file_entry in fs::read_dir(&self.root)? {
            let file_entry = file_entry?;
            let path = file_entry.path();
            if path.extension().map_or(false, |e| e == "jsonl") {
                let file = fs::File::open(&path)?;
                let reader = BufReader::new(file);
                for line in reader.lines() {
                    let line = line?;
                    if line.trim().is_empty() {
                        continue;
                    }
                    if let Ok(entry) = serde_json::from_str::<ExperienceEntry>(&line) {
                        entries.push(entry);
                    }
                }
            }
        }

        // Sort by creation time (most recent first).
        entries.sort_by(|a, b| b.created_at.cmp(&a.created_at));
        Ok(entries)
    }

    /// Build an index over all experience entries.
    pub fn build_index(&self) -> std::io::Result<Vec<ExperienceIndexEntry>> {
        let entries = self.load_all()?;
        Ok(entries
            .into_iter()
            .map(|e| ExperienceIndexEntry {
                id: e.id,
                failure_kind: e.failure_kind,
                tools: e.tools,
                observation_count: e.observation_count,
                created_at: e.created_at,
                preview: truncate_str(&e.what_happened, 80),
            })
            .collect())
    }

    /// Search for experiences matching a query.
    /// Searches in `what_happened`, `correction`, and `tools` fields.
    pub fn search(&self, query: &str) -> std::io::Result<Vec<ExperienceEntry>> {
        let query_lower = query.to_lowercase();
        let all = self.load_all()?;
        Ok(all
            .into_iter()
            .filter(|e| {
                e.what_happened.to_lowercase().contains(&query_lower)
                    || e.correction.to_lowercase().contains(&query_lower)
                    || e.tools.iter().any(|t| t.to_lowercase().contains(&query_lower))
            })
            .collect())
    }

    /// Find experiences for a specific tool.
    pub fn for_tool(&self, tool_name: &str) -> std::io::Result<Vec<ExperienceEntry>> {
        let all = self.load_all()?;
        Ok(all
            .into_iter()
            .filter(|e| e.tools.iter().any(|t| t == tool_name))
            .collect())
    }

    /// Find experiences of a specific failure kind.
    pub fn for_kind(&self, kind: FailureKind) -> std::io::Result<Vec<ExperienceEntry>> {
        let all = self.load_all()?;
        Ok(all
            .into_iter()
            .filter(|e| e.failure_kind == kind)
            .collect())
    }

    /// Count total experience entries.
    pub fn count(&self) -> std::io::Result<usize> {
        Ok(self.load_all()?.len())
    }

    /// Render the N most recent experiences as a system-prompt block.
    /// Returns `None` if there are no experiences or if the budget is 0.
    pub fn render_prompt_block(
        &self,
        char_budget: usize,
        max_items: usize,
    ) -> std::io::Result<Option<String>> {
        if char_budget == 0 || max_items == 0 {
            return Ok(None);
        }

        let entries = self.load_all()?;
        if entries.is_empty() {
            return Ok(None);
        }

        let header = "[Past Experience]\nLearn from these past failures:\n";
        let mut out = String::with_capacity(char_budget);
        out.push_str(header);

        for entry in entries.into_iter().take(max_items) {
            let line = format!(
                "- ({}; observed={}): {} → {}\n",
                entry.failure_kind.label(),
                entry.observation_count,
                truncate_str(&entry.what_happened, 120),
                truncate_str(&entry.correction, 120),
            );
            if out.len() + line.len() > char_budget {
                break;
            }
            out.push_str(&line);
        }

        if out.len() <= header.len() {
            Ok(None)
        } else {
            Ok(Some(out))
        }
    }

    /// Render a summary of all experiences grouped by failure kind.
    pub fn render_summary(&self) -> std::io::Result<ExperienceSummary> {
        let entries = self.load_all()?;
        let mut by_kind: HashMap<FailureKind, Vec<&ExperienceEntry>> = HashMap::new();
        let mut by_tool: HashMap<String, u32> = HashMap::new();

        for e in &entries {
            by_kind.entry(e.failure_kind).or_default().push(e);
            for t in &e.tools {
                *by_tool.entry(t.clone()).or_insert(0) += 1;
            }
        }

        Ok(ExperienceSummary {
            total_entries: entries.len(),
            tool_burst_count: by_kind.get(&FailureKind::ToolBurst).map_or(0, |v| v.len()),
            error_loop_count: by_kind.get(&FailureKind::ErrorLoop).map_or(0, |v| v.len()),
            feedback_pattern_count: by_kind.get(&FailureKind::FeedbackPattern).map_or(0, |v| v.len()),
            convergence_stuck_count: by_kind.get(&FailureKind::ConvergenceStuck).map_or(0, |v| v.len()),
            top_failing_tools: sort_by_value_desc(by_tool.into_iter()).into_iter().take(5).collect(),
        })
    }

    /// Persist a single experience entry to the archive.
    pub fn record(&self, entry: &ExperienceEntry) -> std::io::Result<()> {
        super::harness_self_edit::persist_experience(&self.root, entry)
    }
}

// ---------------------------------------------------------------------------
// Experience summary
// ---------------------------------------------------------------------------

/// Summary statistics of the experience archive.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ExperienceSummary {
    pub total_entries: usize,
    pub tool_burst_count: usize,
    pub error_loop_count: usize,
    pub feedback_pattern_count: usize,
    pub convergence_stuck_count: usize,
    pub top_failing_tools: Vec<(String, u32)>,
}

// ---------------------------------------------------------------------------
// Integration hooks for researcher_loop
// ---------------------------------------------------------------------------

/// Hook called after a researcher step to record any experience.
/// Reads the experience directory and returns a prompt block if
/// there are relevant experiences for the given tools.
pub fn experience_prompt_for_tools(
    archive: &ExperienceArchive,
    tools: &[String],
    char_budget: usize,
) -> std::io::Result<Option<String>> {
    if tools.is_empty() || char_budget == 0 {
        return Ok(None);
    }

    // 一次读完再按工具名筛。`for_tool` 每次调用都会 `load_all()`（遍历目录 +
    // 逐行解析 JSONL），按工具列表逐个调 = **工具数 × 全文读**（默认 ~109 个
    // 工具，而这段在每轮 pre_turn 的同步路径上）。
    let wanted: std::collections::HashSet<&str> = tools.iter().map(String::as_str).collect();
    let mut relevant: Vec<ExperienceEntry> = archive
        .load_all()?
        .into_iter()
        .filter(|e| e.tools.iter().any(|t| wanted.contains(t.as_str())))
        .collect();

    // Deduplicate by ID.
    let mut seen = std::collections::HashSet::new();
    relevant.retain(|e| seen.insert(e.id.clone()));

    if relevant.is_empty() {
        return Ok(None);
    }

    // Sort by recency.
    relevant.sort_by(|a, b| b.created_at.cmp(&a.created_at));

    let header = "[Relevant Past Experience]\n";
    let mut out = String::with_capacity(char_budget);
    out.push_str(header);

    for entry in relevant.into_iter().take(5) {
        let line = format!(
            "- {} → {}\n",
            truncate_str(&entry.what_happened, 100),
            truncate_str(&entry.correction, 100),
        );
        if out.len() + line.len() > char_budget {
            break;
        }
        out.push_str(&line);
    }

    if out.len() <= header.len() {
        Ok(None)
    } else {
        Ok(Some(out))
    }
}

/// Hook called during daily maintenance to produce a summary report.
pub fn daily_experience_report(
    archive: &ExperienceArchive,
) -> std::io::Result<ExperienceSummary> {
    archive.render_summary()
}

/// Hook called during discover to ingest external experience files.
/// Reads JSON files from the `in_external` directory and imports them
/// as experience entries. Returns the number of entries imported.
pub fn ingest_external_experiences(
    archive: &ExperienceArchive,
    in_external: &Path,
) -> std::io::Result<usize> {
    if !in_external.exists() {
        return Ok(0);
    }

    let mut imported = 0usize;
    for entry in fs::read_dir(in_external)? {
        let entry = entry?;
        let path = entry.path();
        if path.extension().map_or(false, |e| e == "json") {
            if let Ok(content) = fs::read_to_string(&path) {
                if let Ok(exp) = serde_json::from_str::<ExperienceEntry>(&content) {
                    archive.record(&exp)?;
                    imported += 1;
                }
            }
        }
    }

    Ok(imported)
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

fn truncate_str(s: &str, max: usize) -> String {
    if s.chars().count() <= max {
        return s.to_string();
    }
    // 切分走 core 的单一实现；省略号计入总长（max-1 字 + …）。
    format!(
        "{}…",
        hermix_core::text_utils::truncate_chars(s, max.saturating_sub(1))
    )
}

// Sorting helper for HashMap iterator.
fn sort_by_value_desc<K, V: Ord>(map: impl Iterator<Item = (K, V)>) -> Vec<(K, V)> {
    let mut v: Vec<_> = map.collect();
    v.sort_by(|a, b| b.1.cmp(&a.1));
    v
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;
    use crate::harness_self_edit::ExperienceEntry;

    fn make_entry(id: &str, kind: FailureKind, tool: &str, count: u32) -> ExperienceEntry {
        ExperienceEntry {
            id: id.into(),
            failure_kind: kind,
            what_happened: format!("Tool `{}` failed", tool),
            correction: format!("Use alternative to `{}`", tool),
            tools: vec![tool.into()],
            observation_count: count,
            created_at: 1000,
        }
    }

    #[test]
    fn archive_open_creates_directory() {
        let tmp = tempfile::tempdir().unwrap();
        let archive_path = tmp.path().join("exp");
        assert!(!archive_path.exists());
        ExperienceArchive::open(&archive_path).unwrap();
        assert!(archive_path.exists());
    }

    #[test]
    fn archive_record_and_load() {
        let tmp = tempfile::tempdir().unwrap();
        let archive = ExperienceArchive::open(tmp.path().join("exp")).unwrap();

        let entry = make_entry("e1", FailureKind::ToolBurst, "shell", 5);
        archive.record(&entry).unwrap();

        let all = archive.load_all().unwrap();
        assert_eq!(all.len(), 1);
        assert_eq!(all[0].id, "e1");
    }

    #[test]
    fn archive_search_by_tool_name() {
        let tmp = tempfile::tempdir().unwrap();
        let archive = ExperienceArchive::open(tmp.path().join("exp")).unwrap();

        archive.record(&make_entry("e1", FailureKind::ToolBurst, "shell", 5)).unwrap();
        archive.record(&make_entry("e2", FailureKind::ToolBurst, "fs_read", 3)).unwrap();

        let results = archive.search("shell").unwrap();
        assert_eq!(results.len(), 1);
        assert_eq!(results[0].id, "e1");
    }

    #[test]
    fn archive_for_tool() {
        let tmp = tempfile::tempdir().unwrap();
        let archive = ExperienceArchive::open(tmp.path().join("exp")).unwrap();

        archive.record(&make_entry("e1", FailureKind::ToolBurst, "shell", 5)).unwrap();
        archive.record(&make_entry("e2", FailureKind::ToolBurst, "fs_read", 3)).unwrap();

        let shell_exp = archive.for_tool("shell").unwrap();
        assert_eq!(shell_exp.len(), 1);
        assert_eq!(shell_exp[0].tools[0], "shell");
    }

    #[test]
    fn archive_for_kind() {
        let tmp = tempfile::tempdir().unwrap();
        let archive = ExperienceArchive::open(tmp.path().join("exp")).unwrap();

        archive.record(&make_entry("e1", FailureKind::ToolBurst, "shell", 5)).unwrap();
        archive.record(&make_entry("e2", FailureKind::ErrorLoop, "shell", 8)).unwrap();

        let burst = archive.for_kind(FailureKind::ToolBurst).unwrap();
        assert_eq!(burst.len(), 1);
    }

    #[test]
    fn archive_render_prompt_block() {
        let tmp = tempfile::tempdir().unwrap();
        let archive = ExperienceArchive::open(tmp.path().join("exp")).unwrap();

        archive.record(&make_entry("e1", FailureKind::ToolBurst, "shell", 5)).unwrap();

        let block = archive.render_prompt_block(1500, 5).unwrap();
        assert!(block.is_some());
        let text = block.unwrap();
        assert!(text.starts_with("[Past Experience]"));
        assert!(text.contains("shell"));
    }

    #[test]
    fn archive_render_prompt_block_empty() {
        let tmp = tempfile::tempdir().unwrap();
        let archive = ExperienceArchive::open(tmp.path().join("exp")).unwrap();

        let block = archive.render_prompt_block(1500, 5).unwrap();
        assert!(block.is_none());
    }

    #[test]
    fn archive_build_index() {
        let tmp = tempfile::tempdir().unwrap();
        let archive = ExperienceArchive::open(tmp.path().join("exp")).unwrap();

        archive.record(&make_entry("e1", FailureKind::ToolBurst, "shell", 5)).unwrap();

        let index = archive.build_index().unwrap();
        assert_eq!(index.len(), 1);
        assert_eq!(index[0].id, "e1");
    }

    #[test]
    fn archive_render_summary() {
        let tmp = tempfile::tempdir().unwrap();
        let archive = ExperienceArchive::open(tmp.path().join("exp")).unwrap();

        archive.record(&make_entry("e1", FailureKind::ToolBurst, "shell", 5)).unwrap();
        archive.record(&make_entry("e2", FailureKind::ErrorLoop, "shell", 8)).unwrap();
        archive.record(&make_entry("e3", FailureKind::ToolBurst, "fs_read", 3)).unwrap();

        let summary = archive.render_summary().unwrap();
        assert_eq!(summary.total_entries, 3);
        assert_eq!(summary.tool_burst_count, 2);
        assert_eq!(summary.error_loop_count, 1);
        assert_eq!(summary.top_failing_tools.len(), 2); // shell + fs_read
        // shell has 2 entries, should be first.
        assert_eq!(summary.top_failing_tools[0].0, "shell");
    }

    /// 完整闭环：计数器 → 分类 → 生成 → 落盘 → 读取 → 渲染进提示词。
    ///
    /// 这条链的每一段早就有单测，但**没有任何测试把两端连起来**——正因如此
    /// 两头都写着、却都不在生产路径上（`classify_convergence` 的注释自己写
    /// 着 "once the harness self-edit integration is complete"）。本测试钉
    /// 住的是"接线后它真的能通"：同一工具失败达到 `SELF_EDIT_TRIGGER` 次，
    /// 经过 `maybe_record_experience` 相同的四个调用，最终能在
    /// `experience_prompt_for_tools` 的输出里读到该工具名。
    #[test]
    fn failure_counter_reaches_the_prompt_block_via_the_archive() {
        use crate::harness_self_edit::{
            classify_tool_failures, generate_experience, SELF_EDIT_TRIGGER,
        };
        use crate::tool_error_demotion::ToolErrorCounter;

        let tmp = tempfile::tempdir().unwrap();
        let mut counter = ToolErrorCounter::new();
        for _ in 0..SELF_EDIT_TRIGGER {
            counter.record_error("terminal");
        }

        let patterns = classify_tool_failures(&counter);
        assert_eq!(patterns.len(), 1, "达到阈值必须产出一个失败模式");

        let archive = ExperienceArchive::open(tmp.path()).unwrap();
        for p in &patterns {
            archive.record(&generate_experience(p)).unwrap();
        }

        let block = experience_prompt_for_tools(
            &archive,
            &["terminal".to_string(), "read_file".to_string()],
            1200,
        )
        .unwrap()
        .expect("刚写入的教训必须能被读出来");
        assert!(block.contains("terminal"), "块里必须点名工具: {block}");
        assert!(block.contains("Relevant Past Experience"), "{block}");

        // 未参与失败的工具不应把这条教训带出来（按工具过滤是刻意的）。
        let other = experience_prompt_for_tools(&archive, &["web_search".to_string()], 1200)
            .unwrap();
        assert!(other.is_none(), "无关工具不该收到这条教训: {other:?}");
    }

    /// 阈值以下不写：一次手滑不值得跨会话留痕。
    #[test]
    fn below_threshold_failures_are_not_archived() {
        use crate::harness_self_edit::classify_tool_failures;
        use crate::tool_error_demotion::ToolErrorCounter;

        let mut counter = ToolErrorCounter::new();
        counter.record_error("terminal");
        counter.record_error("terminal");
        assert!(
            classify_tool_failures(&counter).is_empty(),
            "阈值（{}）之前不应产生模式",
            crate::harness_self_edit::SELF_EDIT_TRIGGER
        );
    }

    #[test]
    fn experience_prompt_for_tools_hook() {
        let tmp = tempfile::tempdir().unwrap();
        let archive = ExperienceArchive::open(tmp.path().join("exp")).unwrap();

        archive.record(&make_entry("e1", FailureKind::ToolBurst, "shell", 5)).unwrap();

        let prompt = experience_prompt_for_tools(
            &archive,
            &["shell".into()],
            1500,
        ).unwrap();
        assert!(prompt.is_some());
        let text = prompt.unwrap();
        assert!(text.contains("[Relevant Past Experience]"));
        assert!(text.contains("shell"));
    }

    #[test]
    fn experience_prompt_for_tools_no_match() {
        let tmp = tempfile::tempdir().unwrap();
        let archive = ExperienceArchive::open(tmp.path().join("exp")).unwrap();

        archive.record(&make_entry("e1", FailureKind::ToolBurst, "shell", 5)).unwrap();

        let prompt = experience_prompt_for_tools(
            &archive,
            &["python".into()],
            1500,
        ).unwrap();
        assert!(prompt.is_none());
    }

    #[test]
    fn ingest_external_experiences_hook() {
        let tmp = tempfile::tempdir().unwrap();
        let archive = ExperienceArchive::open(tmp.path().join("exp")).unwrap();

        // Create an external directory with a JSON file.
        let ext_dir = tmp.path().join("external");
        fs::create_dir_all(&ext_dir).unwrap();
        let entry = make_entry("ext1", FailureKind::FeedbackPattern, "node", 4);
        let json = serde_json::to_string_pretty(&entry).unwrap();
        fs::write(ext_dir.join("ext1.json"), json).unwrap();

        let imported = ingest_external_experiences(&archive, &ext_dir).unwrap();
        assert_eq!(imported, 1);

        let all = archive.load_all().unwrap();
        assert_eq!(all.len(), 1);
        assert_eq!(all[0].id, "ext1");
    }
}
